import { NextRequest, NextResponse } from 'next/server';
import { v4 as uuidv4 } from 'uuid';
import { GoogleGenAI } from '@google/genai';
import {
  getTendencyReport,
  upsertTendencyReport,
  getTerminologyAsContext,
} from '@/lib/db';
import { buildTendencyPrompt } from '@/lib/prompts';

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY || '' });

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const opponentId = searchParams.get('opponent_id');

    if (!opponentId) {
      return NextResponse.json(
        { error: 'opponent_id query parameter is required' },
        { status: 400 }
      );
    }

    const report = getTendencyReport(opponentId);

    if (!report) {
      return NextResponse.json({ report: null });
    }

    // Parse the report_data JSON string for the response
    let reportData;
    try {
      reportData = JSON.parse(report.report_data);
    } catch {
      reportData = report.report_data;
    }

    return NextResponse.json({
      report: {
        ...report,
        report_data: reportData,
      },
    });
  } catch (error: unknown) {
    console.error('Error fetching tendency report:', error);
    const message = error instanceof Error ? error.message : 'Failed to fetch tendency report';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { opponent_id, files } = body;

    if (!opponent_id) {
      return NextResponse.json(
        { error: 'opponent_id is required' },
        { status: 400 }
      );
    }

    if (!files || !Array.isArray(files) || files.length === 0) {
      return NextResponse.json(
        { error: 'files array is required with at least one media file' },
        { status: 400 }
      );
    }

    if (!process.env.GEMINI_API_KEY || process.env.GEMINI_API_KEY === 'your_key_here') {
      return NextResponse.json(
        { error: 'GEMINI_API_KEY not configured. Please add your API key to .env.local' },
        { status: 500 }
      );
    }

    // Build the prompt
    const terminologyContext = getTerminologyAsContext();
    const prompt = buildTendencyPrompt(terminologyContext);

    // Build parts: all media files + text prompt
    const parts: Array<{ inlineData: { mimeType: string; data: string } } | { text: string }> = [];

    for (const file of files) {
      if (file.media && file.mimeType) {
        parts.push({
          inlineData: { mimeType: file.mimeType, data: file.media },
        });
      }
    }

    if (parts.length === 0) {
      return NextResponse.json(
        { error: 'No valid media files found in the request' },
        { status: 400 }
      );
    }

    parts.push({ text: prompt });

    // Call Gemini to analyze the film
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: [{ role: 'user', parts }],
      config: { responseMimeType: 'application/json' },
    });

    const text = response.text || '';

    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch {
      const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (jsonMatch) {
        parsed = JSON.parse(jsonMatch[1].trim());
      } else {
        parsed = JSON.parse(text.trim());
      }
    }

    // Check if there is an existing report to update (increment film count)
    const existingReport = getTendencyReport(opponent_id);
    const reportId = existingReport?.id || uuidv4();
    const filmCount = (existingReport?.film_count || 0) + files.length;

    // Save or update the tendency report
    upsertTendencyReport({
      id: reportId,
      opponent_id,
      report_data: JSON.stringify(parsed),
      film_count: filmCount,
    });

    return NextResponse.json({
      id: reportId,
      opponent_id,
      report_data: parsed,
      film_count: filmCount,
    });
  } catch (error: unknown) {
    console.error('Tendency analysis error:', error);
    const message = error instanceof Error ? error.message : 'Tendency analysis failed';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { v4 as uuidv4 } from 'uuid';
import {
  getAllWeeks,
  insertWeek,
  updateWeek,
  deleteWeek,
  upsertGamePlan,
} from '@/lib/db';

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const seasonYearParam = searchParams.get('season_year');
    const seasonYear = seasonYearParam ? parseInt(seasonYearParam, 10) : undefined;

    const weeks = getAllWeeks(seasonYear);
    return NextResponse.json(weeks);
  } catch (error: unknown) {
    console.error('Error fetching schedule:', error);
    const message = error instanceof Error ? error.message : 'Failed to fetch schedule';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { season_year, week_number, opponent_id, game_date, status, notes } = body;

    if (!season_year || !week_number) {
      return NextResponse.json(
        { error: 'season_year and week_number are required' },
        { status: 400 }
      );
    }

    const weekId = uuidv4();

    insertWeek({
      id: weekId,
      season_year,
      week_number,
      opponent_id: opponent_id || undefined,
      game_date: game_date || undefined,
      status: status || undefined,
      notes: notes || undefined,
    });

    // Auto-create a draft game plan for the new week
    const gamePlanId = uuidv4();
    upsertGamePlan({
      id: gamePlanId,
      week_id: weekId,
      status: 'draft',
    });

    return NextResponse.json(
      { id: weekId, game_plan_id: gamePlanId },
      { status: 201 }
    );
  } catch (error: unknown) {
    console.error('Error creating week:', error);
    const message = error instanceof Error ? error.message : 'Failed to create week';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function PUT(request: NextRequest) {
  try {
    const body = await request.json();
    const { id, ...updates } = body;

    if (!id) {
      return NextResponse.json(
        { error: 'Week id is required in the request body' },
        { status: 400 }
      );
    }

    updateWeek(id, updates);

    return NextResponse.json({ success: true });
  } catch (error: unknown) {
    console.error('Error updating week:', error);
    const message = error instanceof Error ? error.message : 'Failed to update week';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

