export function getAllOpponents(): OpponentRecord[] {
  const database = getDb();
  return database.prepare('SELECT * FROM opponents ORDER BY name').all() as OpponentRecord[];
}

export function getOpponentById(id: string): OpponentRecord | undefined {
  const database = getDb();
  return database.prepare('SELECT * FROM opponents WHERE id = ?').get(id) as OpponentRecord | undefined;
}

export function insertOpponent(opp: OpponentRecord): void {
  const database = getDb();
  database.prepare(
    'INSERT INTO opponents (id, name, abbreviation, notes) VALUES (?, ?, ?, ?)'
  ).run(opp.id, opp.name, opp.abbreviation, opp.notes);
}

export function updateOpponent(id: string, updates: Partial<OpponentRecord>): void {
  const database = getDb();
  const fields: string[] = [];
  const values: unknown[] = [];
  for (const [key, value] of Object.entries(updates)) {
    if (key !== 'id' && key !== 'created_at') {
      fields.push(`${key} = ?`);
      values.push(value);
    }
  }
  if (fields.length === 0) return;
  values.push(id);
  database.prepare(`UPDATE opponents SET ${fields.join(', ')} WHERE id = ?`).run(...values);
}

