export function getAllWeeks(seasonYear?: number): ScheduleRecord[] {
  const database = getDb();
  let query = `SELECT s.*, o.name as opponent_name, o.abbreviation as opponent_abbreviation
               FROM schedule s LEFT JOIN opponents o ON s.opponent_id = o.id`;
  const params: unknown[] = [];
  if (seasonYear) {
    query += ' WHERE s.season_year = ?';
    params.push(seasonYear);
  }
  query += ' ORDER BY s.season_year DESC, s.week_number ASC';
  return database.prepare(query).all(...params) as ScheduleRecord[];
}

export function getWeekById(id: string): ScheduleRecord | undefined {
  const database = getDb();
  return database.prepare(
    `SELECT s.*, o.name as opponent_name, o.abbreviation as opponent_abbreviation
     FROM schedule s LEFT JOIN opponents o ON s.opponent_id = o.id WHERE s.id = ?`
  ).get(id) as ScheduleRecord | undefined;
}

