export function getTerminologyAsContext(): string {
  const terms = getAllTerminology();
  if (terms.length === 0) return '';

  const grouped: Record<string, { standard: string; custom: string }[]> = {};
  for (const t of terms) {
    if (!grouped[t.category]) grouped[t.category] = [];
    grouped[t.category].push({
      standard: t.standard_term,
      custom: t.custom_term,
    });
  }

  let context = 'CUSTOM TERMINOLOGY — Use these terms exclusively:\n';
  for (const [category, mappings] of Object.entries(grouped)) {
    context += `\n[${category.toUpperCase()}]\n`;
    for (const m of mappings) {
      context += `  "${m.standard}" → use "${m.custom}" instead\n`;
    }
  }
  return context;
}

