    const newIdx = index + direction;
    if (newIdx < 0 || newIdx >= script.length) return;
    [script[index], script[newIdx]] = [script[newIdx], script[index]];
    // Re-number
    script.forEach((s, i) => s.order = i + 1);
    const updated = { ...gamePlan, opening_script: JSON.stringify(script) };
    setGamePlan(updated);
    // Persist
    fetch('/api/game-plan', {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: gamePlan.id, opening_script: script }),
    });
  } catch { /* parse error */ }
};

