interface PlayRecord {
  id: string;
  created_at: string;
  defensive_formation: string;
  play_name: string;
  play_type: string;
  full_play_call: string;
  defensive_analysis: string;
  offensive_counter: string;
  whiteboard_data: string;
  media_data: string;
  media_type: string;
  chat_history: string;
  situation_tags: string;
  personnel: string;
  field_zone: string;
  formation: string;
  opponent_id: string;
  week_id: string;
  confidence_rank: number;
}

type Tab = 'overview' | 'tendencies' | 'game-plan' | 'script' | 'call-sheet' | 'sandbox';

const TABS: { key: Tab; label: string }[] = [
  { key: 'overview', label: 'Overview' },
  { key: 'tendencies', label: 'Tendencies' },
  { key: 'game-plan', label: 'Game Plan' },
  { key: 'script', label: 'Script' },
  { key: 'call-sheet', label: 'Call Sheet' },
  { key: 'sandbox', label: 'Sandbox' },
];

const STATUS_FLOW: WeekStatus[] = ['upcoming', 'planning', 'game-week', 'completed'];

// ── Helpers ──────────────────────────────────────────────
function confidenceColor(c: number): string {
  if (c >= 5) return '#00e676';
  if (c >= 4) return '#66ffa6';
  if (c >= 3) return '#ffd740';
  if (c >= 2) return '#ffa726';
  return '#ff5252';
}

function confidenceStars(c: number): string {
  return '\u2605'.repeat(c) + '\u2606'.repeat(5 - c);
}

function getBadgeClass(type: string): string {
  switch (type?.toLowerCase()) {
    case 'pass': return 'badge-pass';
    case 'run': return 'badge-run';
    case 'rpo': return 'badge-rpo';
    case 'screen': return 'badge-screen';
    default: return '';
  }
}

function parseSituationTags(raw: string): string[] {
  try { return JSON.parse(raw); } catch { return []; }
}

function groupPlaysBySituation(plays: PlayRecord[]): Record<string, PlayRecord[]> {
  const groups: Record<string, PlayRecord[]> = {};
  const allSituations = [
    ...DOWN_DISTANCE,
    ...FIELD_ZONES,
    ...SPECIAL_SITUATIONS,
  ];
  for (const s of allSituations) groups[s] = [];
  for (const p of plays) {
    const tags = parseSituationTags(p.situation_tags);
    if (tags.length === 0) {
      if (!groups['Uncategorized']) groups['Uncategorized'] = [];
      groups['Uncategorized'].push(p);
    } else {
      for (const t of tags) {
        if (!groups[t]) groups[t] = [];
        groups[t].push(p);
      }
    }
  }
  return groups;
}

