// ── Confidence color mapping ────────────────────────────
function confidenceColor(conf: number): string {
  switch (conf) {
    case 5: return 'var(--accent)';
    case 4: return 'var(--accent-dim)';
    case 3: return 'var(--warning)';
    case 2: return 'var(--info)';
    case 1: return 'var(--danger)';
    default: return 'var(--text-tertiary)';
  }
}

function typeBadgeStyle(type: string): { bg: string; color: string } {
  switch (type?.toLowerCase()) {
    case 'pass': return { bg: 'rgba(33, 150, 243, 0.15)', color: '#42a5f5' };
    case 'run': return { bg: 'rgba(255, 152, 0, 0.15)', color: '#ffa726' };
    case 'rpo': return { bg: 'rgba(156, 39, 176, 0.15)', color: '#ba68c8' };
    case 'screen': return { bg: 'rgba(0, 230, 118, 0.15)', color: 'var(--accent)' };
    case 'play action': return { bg: 'rgba(255, 215, 64, 0.15)', color: '#ffd740' };
    case 'draw': return { bg: 'rgba(255, 152, 0, 0.12)', color: '#ffb74d' };
    case 'trick/gadget': return { bg: 'rgba(233, 30, 99, 0.15)', color: '#f06292' };
    case 'qb run': return { bg: 'rgba(255, 87, 34, 0.15)', color: '#ff8a65' };
    default: return { bg: 'rgba(255,255,255,0.05)', color: 'var(--text-secondary)' };
  }
}

// ── PlayRow component ───────────────────────────────────
function PlayRow({ play }: { play: CallSheetPlay }) {
  const confColor = confidenceColor(play.confidence);
  const badge = typeBadgeStyle(play.play_type);

  return (
    <div style={{
      display: 'flex',
      alignItems: 'center',
      gap: '8px',
      padding: '4px 8px',
      borderLeft: `3px solid ${confColor}`,
      background: 'rgba(0,0,0,0.15)',
      borderRadius: '0 4px 4px 0',
      marginBottom: '3px',
      minHeight: '28px',
    }}>
      {/* Wristband number */}
      {play.wristband_number != null && (
        <span style={{
          fontFamily: 'var(--font-mono)',
          fontSize: '16px',
          fontWeight: 700,
          color: confColor,
          minWidth: '28px',
          textAlign: 'center',
        }}>
          {play.wristband_number}
        </span>
      )}
      {/* Play name */}
      <span style={{
        flex: 1,
        fontSize: '12px',
        fontWeight: 600,
        color: 'var(--text-primary)',
        whiteSpace: 'nowrap',
        overflow: 'hidden',
        textOverflow: 'ellipsis',
      }}>
        {play.play_name}
      </span>
      {/* Formation */}
      <span style={{
        fontSize: '10px',
        color: 'var(--text-tertiary)',
        whiteSpace: 'nowrap',
        maxWidth: '90px',
        overflow: 'hidden',
        textOverflow: 'ellipsis',
      }}>
        {play.formation}
      </span>
      {/* Personnel badge */}
      <span style={{
        fontSize: '9px',
        fontWeight: 700,
        padding: '1px 5px',
        borderRadius: '8px',
        background: 'rgba(0, 230, 118, 0.1)',
        color: 'var(--accent)',
        letterSpacing: '0.5px',
      }}>
        {play.personnel}
      </span>
      {/* Type badge */}
      <span style={{
        fontSize: '9px',
        fontWeight: 600,
        padding: '1px 5px',
        borderRadius: '8px',
        background: badge.bg,
        color: badge.color,
        letterSpacing: '0.3px',
        textTransform: 'uppercase',
      }}>
        {play.play_type}
      </span>
    </div>
  );
}

// ── SectionCard component ───────────────────────────────
function SectionCard({ label, plays }: { label: string; plays: CallSheetPlay[] }) {
  return (
    <div style={{
      background: 'var(--bg-secondary)',
      border: '1px solid var(--border)',
      borderRadius: 'var(--radius-md)',
      marginBottom: '10px',
      overflow: 'hidden',
      breakInside: 'avoid',
    }}>
      <div style={{
        padding: '6px 10px',
        background: 'var(--bg-tertiary)',
        borderBottom: '1px solid var(--border)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
      }}>
        <span style={{
          fontSize: '11px',
          fontWeight: 700,
          letterSpacing: '1.5px',
          textTransform: 'uppercase',
          color: 'var(--accent)',
        }}>
          {label}
        </span>
        <span style={{
          fontSize: '10px',
          color: 'var(--text-muted)',
          fontFamily: 'var(--font-mono)',
        }}>
          {plays.length}
        </span>
      </div>
      <div style={{ padding: '6px' }}>
        {plays.length === 0 ? (
          <div style={{
            fontSize: '11px',
            color: 'var(--text-muted)',
            textAlign: 'center',
            padding: '8px',
            fontStyle: 'italic',
          }}>
            No plays assigned
          </div>
        ) : (
          plays.map((p, i) => <PlayRow key={p.id || i} play={p} />)
        )}
      </div>
    </div>
  );
}

