const fetchData = useCallback(async () => {
  setLoading(true);
  try {
    // 1. Fetch schedule to find game-week
    const schedRes = await fetch('/api/schedule');
    const weeks: ScheduleWeek[] = await schedRes.json();
    const gw = weeks.find((w) => w.status === 'game-week');

    if (!gw) {
      setActiveWeek(null);
      setLoading(false);
      return;
    }
    setActiveWeek(gw);

    // 2. Fetch game plan for this week
    const gpRes = await fetch(`/api/game-plan?week_id=${gw.id}`);
    const gpData = await gpRes.json();

    if (gpData.game_plan) {
      setGamePlan(gpData.game_plan);

      // Parse call sheet data
      try {
        const cs = typeof gpData.game_plan.call_sheet_data === 'string'
          ? JSON.parse(gpData.game_plan.call_sheet_data)
          : gpData.game_plan.call_sheet_data;
        if (cs && (cs.front_side || cs.back_side)) {
          setCallSheet(cs);
        }
      } catch {
        console.error('Failed to parse call_sheet_data');
      }

      // Parse opening script
      try {
        const script = typeof gpData.game_plan.opening_script === 'string'
          ? JSON.parse(gpData.game_plan.opening_script)
          : gpData.game_plan.opening_script;
        if (Array.isArray(script)) {
          setOpeningScript(script);
        }
      } catch {
        console.error('Failed to parse opening_script');
      }
    }
  } catch (err) {
    console.error('Failed to fetch game day data:', err);
  } finally {
    setLoading(false);
  }
}, []);

