import { NextRequest, NextResponse } from 'next/server';
import { v4 as uuidv4 } from 'uuid';
import { getAllOpponents, insertOpponent, deleteOpponent } from '@/lib/db';

export async function GET() {
  try {
    const opponents = getAllOpponents();
    return NextResponse.json(opponents);
  } catch (error: unknown) {
    console.error('Error fetching opponents:', error);
    const message = error instanceof Error ? error.message : 'Failed to fetch opponents';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { name, abbreviation, notes } = body;

    if (!name || typeof name !== 'string' || name.trim().length === 0) {
      return NextResponse.json(
        { error: 'Opponent name is required' },
        { status: 400 }
      );
    }

    const opponent = {
      id: uuidv4(),
      name: name.trim(),
      abbreviation: abbreviation || '',
      notes: notes || '',
      created_at: new Date().toISOString(),
    };

    insertOpponent(opponent);

    return NextResponse.json(opponent, { status: 201 });
  } catch (error: unknown) {
    console.error('Error creating opponent:', error);
    const message = error instanceof Error ? error.message : 'Failed to create opponent';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function DELETE(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const id = searchParams.get('id');

    if (!id) {
      return NextResponse.json(
        { error: 'Opponent id is required as a query parameter' },
        { status: 400 }
      );
    }

    deleteOpponent(id);

    return NextResponse.json({ success: true });
  } catch (error: unknown) {
    console.error('Error deleting opponent:', error);
    const message = error instanceof Error ? error.message : 'Failed to delete opponent';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

