// ── Opponents ──────────────────────────────────────────
export interface Opponent {
  id: string;
  name: string;
  abbreviation: string;
  notes: string;
  created_at: string;
}

// ── Season Schedule ────────────────────────────────────
export type WeekStatus = 'upcoming' | 'planning' | 'game-week' | 'completed';

export interface ScheduleWeek {
  id: string;
  season_year: number;
  week_number: number;
  opponent_id: string | null;
  game_date: string;
  status: WeekStatus;
  notes: string;
  created_at: string;
  // joined fields
  opponent_name?: string;
  opponent_abbreviation?: string;
}

// ── Game Plans ─────────────────────────────────────────
export type GamePlanStatus = 'draft' | 'in-progress' | 'finalized';

export interface GamePlan {
  id: string;
  week_id: string;
  status: GamePlanStatus;
  opening_script: string;    // JSON array of play references
  call_sheet_data: string;   // JSON organized by situation
  tendency_notes: string;
  notes: string;
  created_at: string;
  updated_at: string;
}

// ── Tendency Reports ───────────────────────────────────
export interface TendencyReport {
  id: string;
  opponent_id: string;
  report_data: string;  // JSON with full tendency breakdown
  film_count: number;
  created_at: string;
  updated_at: string;
}

export interface TendencyData {
  formations: { name: string; count: number; percentage: number }[];
  coverages: { name: string; count: number; percentage: number }[];
  blitz: {
    overall_rate: number;
    by_down: Record<string, number>;
    types: { name: string; count: number }[];
  };
  fronts: { name: string; count: number; percentage: number }[];
  personnel: { grouping: string; count: number; percentage: number }[];
  run_pass_splits: Record<string, { run: number; pass: number }>;
  vulnerabilities: string[];
  high_confidence_reads: string[];  // 70%+ tendencies
  key_players: { position: string; number: string; notes: string }[];
  overall_assessment: string;
}

