101	    // Build prompt and call Gemini
102	    const terminologyContext = getTerminologyAsContext();
103	    const prompt = buildGamePlanPrompt(terminologyContext, tendencyData, playsContext);
104	
105	    const response = await ai.models.generateContent({
106	      model: 'gemini-3-pro-preview',
107	      contents: [{ role: 'user', parts: [{ text: prompt }] }],
108	      config: { responseMimeType: 'application/json' },
109	    });
110	
111	    const text = response.text || '';
112	
113	    let parsed: GeneratedGamePlan;
114	    try {
115	      parsed = JSON.parse(text);
116	    } catch {
117	      const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
118	      if (jsonMatch) {
119	        parsed = JSON.parse(jsonMatch[1].trim());
120	      } else {
121	        parsed = JSON.parse(text.trim());
