145	export function getAllPlays(filters?: {
146	  play_type?: string;
147	  search?: string;
148	  opponent_id?: string;
149	  week_id?: string;
150	  personnel?: string;
151	  situation?: string;
152	  field_zone?: string;
153	}): PlayRecord[] {
154	  const database = getDb();
155	  let query = 'SELECT * FROM plays';
156	  const conditions: string[] = [];
157	  const params: string[] = [];
158	
159	  if (filters?.play_type && filters.play_type !== 'All') {
160	    conditions.push('play_type = ?');
161	    params.push(filters.play_type);
162	  }
163	  if (filters?.search) {
164	    conditions.push(
165	      '(play_name LIKE ? OR defensive_formation LIKE ? OR full_play_call LIKE ? OR formation LIKE ?)'
166	    );
167	    const term = `%${filters.search}%`;
168	    params.push(term, term, term, term);
169	  }
170	  if (filters?.opponent_id) {
171	    conditions.push('opponent_id = ?');
172	    params.push(filters.opponent_id);
173	  }
174	  if (filters?.week_id) {
175	    conditions.push('week_id = ?');
176	    params.push(filters.week_id);
177	  }
178	  if (filters?.personnel) {
179	    conditions.push('personnel = ?');
180	    params.push(filters.personnel);
181	  }
182	  if (filters?.situation) {
183	    conditions.push('situation_tags LIKE ?');
184	    params.push(`%${filters.situation}%`);
185	  }
186	  if (filters?.field_zone) {
187	    conditions.push('field_zone = ?');
188	    params.push(filters.field_zone);
189	  }
190	
191	  if (conditions.length > 0) {
192	    query += ' WHERE ' + conditions.join(' AND ');
193	  }
194	  query += ' ORDER BY created_at DESC';
195	
196	  return database.prepare(query).all(...params) as PlayRecord[];
197	}
